          const top=target.stack.pop();foe.deck.push({uid:'ex12-cradily-'+turn+'-'+top+'-'+target.uid,cardId:top});
          target.cardId=target.stack[target.stack.length-1];ctx.shuffle?.(ctx.state,foe.deck);
